import{_ as d,l,o as a,c as i,v as r,p as s,x as t,d as n,i as p,S as _}from"./chunks/framework.InCnrqk-.js";const O=JSON.parse('{"title":"RTO 与恢复","description":"","frontmatter":{"title":"RTO 与恢复","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rto-recovery.md","filePath":"cs/rto-recovery.md","lastUpdated":1789023840000}'),c={name:"cs/rto-recovery.md"};function T(R,e,E,h,u,m){const o=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=r('<h1 id="rto-与恢复" tabindex="-1">RTO 与恢复 <a class="header-anchor" href="#rto-与恢复" aria-label="Permalink to &quot;RTO 与恢复&quot;">​</a></h1><div class="epigraph"><p>RTO 是允许的停机预算：分析+redo+undo+打开连接要落在预算内。检查点间隔、日志设备、并行 redo 是杠杆，不是口号。</p><footer>—— 据 Gray and Reuter 恢复时间；ARIES 三阶段；运维 RTO/RPO</footer></div><p><a href="/cs/durability-levels">上一课</a>钉了丢多少。本课钉<strong>多久能服务</strong>：恢复时间目标（RTO）。模糊检查点缩短 redo 前缀；并行 redo 缩短墙钟；undo 未决事务量也算。备份后课是另一条「从零拉起到某时间点」的 RTO。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>崩溃：启动三阶段。redo 体积 ≈ 检查点以来的日志 × 应用速度。脏页多、日志在慢盘、单线程 redo，RTO 爆炸。缺口是把恢复当性能路径设计：日志盘、redo 并行度、检查点节奏、崩溃时未决事务数（长事务 undo 长）。</p><p>演练：不演练的 RTO 是假的。与计划回归不同，这是运维不变式。</p><p><span class="marginnote">RTO 含故障检测、选主、DNS、连接池排空。本课核心是库进程恢复。检测与租约在分布式课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算分解：检测 \\(t_d\\) + 分析 \\(t_a\\) + redo \\(t_r\\) + undo \\(t_u\\) + 预热 \\(t_w\\)。杠杆：更频检查点降 \\(t_r\\)；限制长事务降 \\(t_u\\)；备库升主把 \\(t_r\\) 换成复制延迟（可能更短）。预热：缓冲池空则刚恢复仍慢，要预热或接受缓存冷。</p><p>监控：上次恢复各阶段耗时。日志积压告警等于 RTO 恶化预警。</p>',10)),(a(),s(_,null,{default:t(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CRASH%5B%22%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20DET%5B%22%E6%A3%80%E6%B5%8B%22%5D%0A%20%20DET%20--%3E%20REC%5B%22%E5%88%86%E6%9E%90%20redo%20undo%22%5D%0A%20%20REC%20--%3E%20OPEN%5B%22%E6%8E%A5%E5%8F%97%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20OPEN%20--%3E%20WARM%5B%22%E7%BC%93%E5%86%B2%E9%A2%84%E7%83%AD%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与组提交无关直接，但日志设备共享会让运行与恢复抢。doublewrite 恢复先修页，计入 \\(t_r\\)。逻辑重放备库的 RTO 是重放追上，不是 ARIES。</p><p>云盘快照恢复：RTO 含挂载与 WAL 追，粒度不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 PITR 选时间点。也不把 RTO 当隔离级别。半同步影响的是故障时 RPO 与是否能立刻升主。</p><p>后课默认：RTO 可分解、可演练、用检查点与并行 redo 调。备份与 PITR：从备份基线+日志前滚到任意点。</p><p>没有预热的「已恢复」对用户仍是超时。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RTO 分解为检测与三阶段加预热。</li><li>检查点、并行 redo、限制长事务是杠杆。</li><li>备份与 PITR 下一课。</li><li>出处：Gray and Reuter；ARIES；RTO/RPO 实践。</li></ul>',9))])}const f=d(c,[["render",T]]);export{O as __pageData,f as default};
